use crate::aap::caps::inference_llm;

struct Node;

/// Map the model's free-text label to the closed `Intent` enum. Anything we do
/// not recognise collapses to `Unknown`; the enum has no "other" case, so
/// adversarial text cannot widen the intent set (the `ensures` on `intent` holds
/// by construction).
fn parse_intent(raw: &str) -> Intent {
    let norm: String = raw
        .trim()
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c == '-' || c == ' ' { '_' } else { c })
        .collect();
    match norm.as_str() {
        s if s.contains("billing") => Intent::BillingQuestion,
        s if s.contains("technical") || s.contains("tech_support") || s.contains("support") => {
            Intent::TechnicalSupport
        }
        s if s.contains("account") => Intent::AccountChange,
        s if s.contains("general") || s.contains("inquiry") => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Truncate to at most `max` bytes without splitting a UTF-8 char. Enforces
/// `len(question) <= 512`.
fn clamp_bytes(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let text = message.text;

        let system = "You are a message classifier for a customer support system. \
Read the user's message and reply with exactly one of these labels and nothing else: \
billing_question, technical_support, account_change, general_inquiry, unknown.";

        let label = inference_llm::infer(system, &text, "classify");
        let intent = parse_intent(&label);

        // The bounded, still-adversarial residual: the user's own text, clamped
        // to the 512-byte postcondition. No entities are extracted here.
        let question = clamp_bytes(text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
